"use client";
import { useEffect, useState } from "react";
import { baseSkills, selectDailyTasks, taskChecks, tasks, type Task } from "./data";

type View="dashboard"|"train"|"matrix"|"journal"|"admin";
type Phase="observe"|"model"|"hypothesize"|"plan"|"act"|"verify"|"update"|"learn"|"result";
type Diagnosis={phenomenon:string;facts:string;hypothesis:string;firstCheckpoint:string;supportingEvidence:string;counterEvidence:string;nextExperiment:string};
type Observation={signals:string;knownFacts:string;unknowns:string;sources:string;user:string;why:string;what:string;input:string;output:string;constraints:string;successMetric:string;failureCondition:string;requirementApproval:""|"approve"|"reopen"};
type SystemModel={boundary:string;currentState:string;expectedState:string;transition:string;callChain:string;dataFlow:string;dependencies:string;runtimeState:string;candidateSolutions:string;tradeoffs:string;risks:string;decisionRecord:string;solutionApproval:""|"approve"|"revise"|"reject"};
type ActionPlan={candidateActions:string;nextBestAction:string;selectedTool:string;informationGain:number;expectedObservation:string;cost:"low"|"medium"|"high";risk:"low"|"medium"|"high";fallback:string;scopeGoal:string;proposedFiles:string;impactAnalysis:string;excludedChanges:string;contextBudget:string;approvalDecision:""|"approve"|"split"|"reject"};
type StateUpdate={actionResult:string;newObservation:string;modelChanged:string;hypothesisStatus:string;replannedAction:string};
type Evidence={action:string;actual:string;dataState:string;reason:string};
type Reflection={initialJudgment:string;actualRootCause:string;wrongAssumption:string;keyEvidence:string;helpfulHint:string;nextFirstStep:string;designRationale:string;alternative:string;largestRisk:string;refactorTrigger:string};
type ReviewDecision={decision:""|"accept"|"reject"|"changes";scopeDecision:""|"accept"|"reject"|"split"|"rollback"|"smaller";riskLevel:"P0"|"P1"|"P2"|"P3";issues:string;rationale:string;revisionRequest:string;understanding:string;rollback:string;architectureDriftDetected:boolean;impactApproved:boolean;finalApproval:boolean;reviewCapacity:number;trustBefore:number;trustAfter:number;suggestionDecisions:Record<string,"accept"|"reject"|"defer"|"ignore">};
type FunnelDecision={stage:"Requirement"|"Solution"|"Implementation"|"Acceptance";decision:string;at:string};
type TestResult={label:string;passed:boolean;input:string;actual:string;databaseState:string;why:string};
type Session={id:number;task_id:string;variant_id:string;task_title:string;diagnosis:string;evidence:string;reflection:string;review:string;specification:string;release_readiness:string;test_results:string;hints_used:number;first_hint_seconds:number;autonomous_diagnosis:boolean;independent_completion:boolean;ai_dependency_score:number;ai_judgment_score:number;engineering_ownership_score:number;ai_claim_confidence:number;ai_claim_accurate:boolean;architecture_drift_detected:boolean;score:number;skill_gains_json:string;duration_seconds:number;completed_at:string};
const blankDiagnosis:Diagnosis={phenomenon:"",facts:"",hypothesis:"",firstCheckpoint:"",supportingEvidence:"",counterEvidence:"",nextExperiment:""};
const blankObservation:Observation={signals:"",knownFacts:"",unknowns:"",sources:"",user:"",why:"",what:"",input:"",output:"",constraints:"",successMetric:"",failureCondition:"",requirementApproval:""};
const blankSystemModel:SystemModel={boundary:"",currentState:"",expectedState:"",transition:"",callChain:"",dataFlow:"",dependencies:"",runtimeState:"",candidateSolutions:"",tradeoffs:"",risks:"",decisionRecord:"",solutionApproval:""};
const blankActionPlan:ActionPlan={candidateActions:"",nextBestAction:"",selectedTool:"",informationGain:50,expectedObservation:"",cost:"low",risk:"medium",fallback:"",scopeGoal:"",proposedFiles:"",impactAnalysis:"",excludedChanges:"",contextBudget:"",approvalDecision:""};
const blankStateUpdate:StateUpdate={actionResult:"",newObservation:"",modelChanged:"",hypothesisStatus:"",replannedAction:""};
const blankEvidence:Evidence={action:"",actual:"",dataState:"",reason:""};
const blankReflection:Reflection={initialJudgment:"",actualRootCause:"",wrongAssumption:"",keyEvidence:"",helpfulHint:"",nextFirstStep:"",designRationale:"",alternative:"",largestRisk:"",refactorTrigger:""};
const blankReview:ReviewDecision={decision:"",scopeDecision:"",riskLevel:"P1",issues:"",rationale:"",revisionRequest:"",understanding:"",rollback:"",architectureDriftDetected:false,impactApproved:false,finalApproval:false,reviewCapacity:180,trustBefore:50,trustAfter:30,suggestionDecisions:{}};
const toolNames:Record<string,string>={code:"代码",logs:"日志",network:"网络",api:"API",sql:"SQL",db:"数据库",docker:"Docker",env:"环境",search:"搜索",runtime:"运行态",diff:"Diff",tests:"验收"};
const initialDailyTasks=selectDailyTasks([],baseSkills);
const initialTask=initialDailyTasks[0];
const initialFiles=initialTask.files?.length?initialTask.files:[{path:initialTask.contextTitle,language:"text",content:initialTask.context}];

function safeObject<T>(value:string,fallback:T):T{try{return JSON.parse(value) as T}catch{return fallback}}
function textFrom(value:string){const parsed=safeObject<unknown>(value,value);const flatten=(item:unknown):string[]=>typeof item==="string"?[item]:Array.isArray(item)?item.flatMap(flatten):item&&typeof item==="object"?Object.values(item).flatMap(flatten):[];return flatten(parsed).filter(Boolean).slice(0,8).join(" · ")||value}
function average(values:number[]){return values.length?Math.round(values.reduce((sum,value)=>sum+value,0)/values.length):0}

export default function Home(){
  const [view,setView]=useState<View>("dashboard");const [dailyTasks,setDailyTasks]=useState<Task[]>(initialDailyTasks);const [task,setTask]=useState<Task>(initialTask);
  const [skills,setSkills]=useState<Record<string,number>>(baseSkills);const [sessions,setSessions]=useState<Session[]>([]);const [xp,setXp]=useState(680);const [streak,setStreak]=useState(7);const [catalogSize,setCatalogSize]=useState(tasks.length);const [variantCapacity,setVariantCapacity]=useState(tasks.length*5);
  const [phase,setPhase]=useState<Phase>("observe");const [observation,setObservation]=useState<Observation>(blankObservation);const [systemModel,setSystemModel]=useState<SystemModel>(blankSystemModel);const [diagnosis,setDiagnosis]=useState<Diagnosis>(blankDiagnosis);const [actionPlan,setActionPlan]=useState<ActionPlan>(blankActionPlan);const [evidence,setEvidence]=useState<Evidence>(blankEvidence);const [stateUpdate,setStateUpdate]=useState<StateUpdate>(blankStateUpdate);const [reflection,setReflection]=useState<Reflection>(blankReflection);
  const [reviewDecision,setReviewDecision]=useState<ReviewDecision>(blankReview);const [specificationCoverage,setSpecificationCoverage]=useState<string[]>([]);const [releaseChecks,setReleaseChecks]=useState<string[]>([]);const [funnelHistory,setFunnelHistory]=useState<FunnelDecision[]>([]);
  const [workspace,setWorkspace]=useState<Record<string,string>>(()=>Object.fromEntries(initialFiles.map(file=>[file.path,file.content])));const [selectedFile,setSelectedFile]=useState(initialFiles[0].path);const [panel,setPanel]=useState("code");const [toolUsage,setToolUsage]=useState<string[]>([]);const [hints,setHints]=useState(0);const [firstHintSeconds,setFirstHintSeconds]=useState(0);const [diagnosisLockedBeforeHint,setDiagnosisLockedBeforeHint]=useState(true);const [startedAt,setStartedAt]=useState(0);
  const [results,setResults]=useState<TestResult[]>([]);const [notice,setNotice]=useState("");const [saving,setSaving]=useState(false);const [resultMetrics,setResultMetrics]=useState({score:100,aiDependencyScore:0,aiJudgmentScore:0,engineeringOwnershipScore:0,specificationScore:0,releaseScore:0,systemModelingScore:0,planningScore:0,hypothesisScore:0,falsificationScore:0,observationScore:0,stateUpdateScore:0,toolSelectionScore:0,verificationScore:0,cognitiveDebtScore:0,reviewCoverage:0,understandingCoverage:0,diffReviewScore:0,scopeControlScore:0,architectureControlScore:0,changeRiskScore:0,generationReviewRatio:0,requirementQualityScore:0,solutionQualityScore:0,implementationPlanningScore:0,acceptanceQualityScore:0,engineeringConvergenceScore:0});
  useEffect(()=>{fetch("/api/progress").then(response=>response.json()).then(data=>{if(data.profile){setXp(data.profile.xp);setStreak(data.profile.streak);setSkills(safeObject(data.profile.skills_json,baseSkills))}if(Array.isArray(data.sessions))setSessions(data.sessions);if(Array.isArray(data.dailyTasks)&&data.dailyTasks.length){setDailyTasks(data.dailyTasks);setTask(data.dailyTasks[0])}setCatalogSize(data.catalogSize??tasks.length);setVariantCapacity(data.variantCapacity??tasks.length*5)}).catch(()=>undefined)},[]);
  const score=average(Object.values(skills));const rank=score>=80?"L4 · DELIVERY LEAD":score>=65?"L3 · INDEPENDENT":score>=50?"L2 · CONTRIBUTOR":"L1 · STARTER";

  function openTask(next:Task){const files=next.files?.length?next.files:[{path:next.contextTitle,language:"text",content:next.context}];setTask(next);setWorkspace(Object.fromEntries(files.map(file=>[file.path,file.content])));setSelectedFile(files[0].path);setPhase("observe");setObservation({...blankObservation});setSystemModel({...blankSystemModel});setDiagnosis({...blankDiagnosis});setActionPlan({...blankActionPlan});setEvidence({...blankEvidence});setStateUpdate({...blankStateUpdate});setReflection({...blankReflection});setReviewDecision({...blankReview,trustBefore:next.aiSubmission?.confidence??50});setSpecificationCoverage([]);setReleaseChecks([]);setFunnelHistory([]);setPanel("code");setToolUsage([]);setHints(0);setFirstHintSeconds(0);setDiagnosisLockedBeforeHint(true);setStartedAt(Date.now());setResults([]);setNotice("");setView("train");window.scrollTo({top:0,behavior:"smooth"})}
  function recordGate(stage:FunnelDecision["stage"],decision:string){setFunnelHistory(current=>[...current,{stage,decision,at:new Date().toISOString()}])}
  function reopenRequirement(){setObservation(current=>({...current,requirementApproval:"reopen"}));setSystemModel(current=>({...current,solutionApproval:""}));setActionPlan(current=>({...current,approvalDecision:""}));setReviewDecision(current=>({...current,finalApproval:false}));recordGate("Requirement","需求变化：重新打开并重新计算后续范围");setPhase("observe");setNotice("需求已重新打开。重新批准前，方案、实现与验收阶段保持锁定。");window.scrollTo({top:0,behavior:"smooth"})}
  function selectTool(name:string){setPanel(name);setToolUsage(current=>current.includes(name)?current:[...current,name])}
  function requestHint(){if(hints>=3)return;if(!firstHintSeconds)setFirstHintSeconds(Math.round((Date.now()-startedAt)/1000));if(["observe","model","hypothesize","plan"].includes(phase))setDiagnosisLockedBeforeHint(false);setHints(value=>value+1)}
  function advanceObserve(){const required=[observation.user,observation.why,observation.what,observation.input,observation.output,observation.constraints,observation.successMetric,observation.failureCondition];if(observation.signals.trim().length<6||observation.knownFacts.trim().length<6||observation.unknowns.trim().length<4||required.some(value=>value.trim().length<4)){setNotice("需求漏斗必须回答 Who、Why、What、Input、Output、Constraint、Success Metric 和 Failure Condition。");return}if(observation.requirementApproval!=="approve"){setNotice("Requirement Not Approved → Cannot Enter Solution。请由人类锁定需求。");return}recordGate("Requirement","APPROVED · 需求范围与成功定义已锁定");setNotice("");setPhase("model")}
  function advanceModel(){if(systemModel.boundary.trim().length<6||systemModel.currentState.trim().length<6||systemModel.expectedState.trim().length<6||systemModel.callChain.trim().length<6||systemModel.candidateSolutions.trim().length<8||systemModel.tradeoffs.trim().length<8||systemModel.risks.trim().length<6||systemModel.decisionRecord.trim().length<8){setNotice("方案漏斗必须包含候选方案、权衡、风险和架构决策记录。");return}if(systemModel.solutionApproval!=="approve"){setNotice("Solution Not Approved → Cannot Generate Code。请先完成人工架构审批。");return}recordGate("Solution","APPROVED · 架构方案与约束已冻结");setNotice("");setPhase("hypothesize")}
  function lockDiagnosis(){if(diagnosis.phenomenon.trim().length<6||diagnosis.hypothesis.trim().length<8||diagnosis.firstCheckpoint.trim().length<6||diagnosis.counterEvidence.trim().length<6){setNotice("请至少写清现象、根因假设、第一个检查点和反证条件。");return}setNotice("");setPhase("plan")}
  function advancePlan(){if(actionPlan.candidateActions.trim().length<8||actionPlan.nextBestAction.trim().length<6||actionPlan.selectedTool.trim().length<2||actionPlan.expectedObservation.trim().length<6||actionPlan.scopeGoal.trim().length<6||actionPlan.proposedFiles.trim().length<4||actionPlan.impactAnalysis.trim().length<8){setNotice("规划必须包含范围目标、文件清单、影响分析、候选动作和预期观察。");return}if(actionPlan.approvalDecision!=="approve"){setNotice("只有人工明确批准当前小批次后，AI 才能进入实现。");return}recordGate("Implementation","APPROVED · 文件、预算与 AI 执行边界已锁定");selectTool(actionPlan.selectedTool);setNotice("");setPhase("act")}
  function runTests(){const combined=Object.values(workspace).join("\n").toLocaleLowerCase().replace(/\s+/g,"");const checks=taskChecks[task.id]??[];const next=task.criteria.map((label,index)=>{const check=checks[index];const changed=combined!==task.context.toLocaleLowerCase().replace(/\s+/g,"");const passed=check?check.groups.every(group=>group.some(token=>combined.includes(token.toLocaleLowerCase().replace(/\s+/g,"")))):changed&&combined.length>80;return{label,passed,input:`acceptance case ${String(index+1).padStart(2,"0")}`,actual:passed?"断言通过，输出符合任务约束":check?.failureHint??"尚未观察到有效改动",databaseState:passed?(index===0?"目标状态已写入并可重新读取":"无意外副作用或重复记录"):"未满足验收前置条件",why:passed?"实现、输出与持久化状态形成一致证据链":"当前结果不能证明业务不变量成立"}});setResults(next);selectTool("tests");setNotice(next.every(result=>result.passed)?"4 项验收全部通过。请整理证据链。":"仍有验收项失败。展开结果查看输入、实际输出和数据状态。")}
  function goEvidence(){const budget=task.changeBudget;const generated=task.aiSubmission;const overBudget=Boolean(budget&&generated&&((generated.filesChanged??0)>budget.maxFiles||(generated.linesAdded??0)>budget.maxLines||(generated.newDependencies??0)>budget.maxDependencies||(generated.migrations??0)>budget.maxMigrations));if(!reviewDecision.decision||!reviewDecision.scopeDecision||reviewDecision.issues.trim().length<8||reviewDecision.rationale.trim().length<8||reviewDecision.understanding.trim().length<8||reviewDecision.rollback.trim().length<6){setNotice("先完成 Diff 审查：范围决定、风险、理解说明和回滚方法都不能为空。");return}if(overBudget&&reviewDecision.scopeDecision==="accept"){setNotice("AI 输出已超过审查容量，不能整包接受；请拆分、拒绝、回滚或要求更小改动。");return}if((budget?.impactAnalysisRequired||(generated?.newDependencies??0)>0||(generated?.migrations??0)>0)&&!reviewDecision.impactApproved){setNotice("跨模块、依赖、架构或数据库影响必须经过单独审批。");return}if(task.type==="SPECIFICATION LAB"&&specificationCoverage.length<8){setNotice("规格训练至少需要覆盖 8 个工程维度。");return}if(results.length!==4||results.some(result=>!result.passed)){setNotice("必须先让 4 项验收全部通过。");return}recordGate("Implementation","REVIEWED · Diff 已理解，自动验收全部通过");setNotice("");setPhase("verify")}
  function goUpdate(){if(evidence.action.trim().length<4||evidence.actual.trim().length<4||evidence.reason.trim().length<8){setNotice("证据需要包含执行动作、实际输出和为什么能证明结论。");return}setNotice("");setPhase("update")}
  function goLearn(){if(stateUpdate.actionResult.trim().length<6||stateUpdate.newObservation.trim().length<6||stateUpdate.modelChanged.trim().length<6||stateUpdate.hypothesisStatus.trim().length<6){setNotice("更新阶段必须记录行动结果、新观察、模型变化和假设状态。");return}setNotice("");setPhase("learn")}
  async function complete(){if(reflection.actualRootCause.trim().length<8||reflection.keyEvidence.trim().length<8||reflection.nextFirstStep.trim().length<6){setNotice("请完成真实根因、关键证据和下次第一步，再提交复盘。");return}if(releaseChecks.length<8){setNotice("上线前至少核验 8 项 Definition of Done 证据。");return}if(!reviewDecision.finalApproval){setNotice("AI 不能自行宣布完成。请在证据齐全后执行最终人工验收批准。");return}recordGate("Acceptance","APPROVED · Evidence Before Done");setSaving(true);setNotice("");try{const response=await fetch("/api/progress",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({taskId:task.id,variantId:task.variantId??task.id,taskTitle:task.title,observation,systemModel,diagnosis,actionPlan,evidence,stateUpdate,reflection,reviewDecision,funnelHistory:[...funnelHistory,{stage:"Acceptance",decision:"APPROVED · Evidence Before Done",at:new Date().toISOString()}],specificationCoverage,releaseChecks,testResults:results,toolUsage,hintsUsed:hints,firstHintSeconds,autonomousDiagnosis:diagnosisLockedBeforeHint,durationSeconds:Math.round((Date.now()-startedAt)/1000)})});const data=await response.json();if(!response.ok)throw new Error(data.error||"save failed");setSkills(data.skills);setXp(data.xp);setResultMetrics({score:data.score,aiDependencyScore:data.aiDependencyScore,aiJudgmentScore:data.aiJudgmentScore,engineeringOwnershipScore:data.engineeringOwnershipScore,specificationScore:data.specificationScore,releaseScore:data.releaseScore,systemModelingScore:data.systemModelingScore,planningScore:data.planningScore,hypothesisScore:data.hypothesisScore,falsificationScore:data.falsificationScore,observationScore:data.observationScore,stateUpdateScore:data.stateUpdateScore,toolSelectionScore:data.toolSelectionScore,verificationScore:data.verificationScore,cognitiveDebtScore:data.cognitiveDebtScore,reviewCoverage:data.reviewCoverage,understandingCoverage:data.understandingCoverage,diffReviewScore:data.diffReviewScore,scopeControlScore:data.scopeControlScore,architectureControlScore:data.architectureControlScore,changeRiskScore:data.changeRiskScore,generationReviewRatio:data.generationReviewRatio,requirementQualityScore:data.requirementQualityScore,solutionQualityScore:data.solutionQualityScore,implementationPlanningScore:data.implementationPlanningScore,acceptanceQualityScore:data.acceptanceQualityScore,engineeringConvergenceScore:data.engineeringConvergenceScore});setSessions(current=>[data.attempt,...current]);setPhase("result")}catch{setNotice("训练轨迹已保留，但数据库暂时不可用。请稍后重试。")}finally{setSaving(false)}}

  return <div className="app-shell"><Header view={view} setView={setView} streak={streak} rank={rank}/>{view==="dashboard"&&<Dashboard tasks={dailyTasks} openTask={openTask} score={score} sessions={sessions} skills={skills} catalogSize={catalogSize} variantCapacity={variantCapacity}/>} {view==="train"&&<Training task={task} phase={phase} setPhase={setPhase} observation={observation} setObservation={setObservation} systemModel={systemModel} setSystemModel={setSystemModel} diagnosis={diagnosis} setDiagnosis={setDiagnosis} actionPlan={actionPlan} setActionPlan={setActionPlan} evidence={evidence} setEvidence={setEvidence} stateUpdate={stateUpdate} setStateUpdate={setStateUpdate} reflection={reflection} setReflection={setReflection} reviewDecision={reviewDecision} setReviewDecision={setReviewDecision} specificationCoverage={specificationCoverage} setSpecificationCoverage={setSpecificationCoverage} releaseChecks={releaseChecks} setReleaseChecks={setReleaseChecks} funnelHistory={funnelHistory} reopenRequirement={reopenRequirement} workspace={workspace} setWorkspace={setWorkspace} selectedFile={selectedFile} setSelectedFile={setSelectedFile} panel={panel} selectTool={selectTool} results={results} runTests={runTests} advanceObserve={advanceObserve} advanceModel={advanceModel} lockDiagnosis={lockDiagnosis} advancePlan={advancePlan} goEvidence={goEvidence} goUpdate={goUpdate} goLearn={goLearn} complete={complete} hints={hints} requestHint={requestHint} notice={notice} saving={saving} metrics={resultMetrics} dailyTasks={dailyTasks} openTask={openTask}/>} {view==="matrix"&&<SkillMatrix skills={skills} sessions={sessions} score={score} rank={rank}/>} {view==="journal"&&<Journal sessions={sessions} openTask={openTask} fallback={dailyTasks[0]}/>} {view==="admin"&&<Admin catalogSize={catalogSize}/>}<footer><p>FORGE · AI ENGINEERING COACH</p><span>DEFINE · DESIGN · BUILD · PROVE</span><span>{xp} XP</span></footer></div>
}

function Header({view,setView,streak,rank}:{view:View;setView:(view:View)=>void;streak:number;rank:string}){return <header className="topbar"><button className="brand" onClick={()=>setView("dashboard")}><span>F</span> FORGE</button><nav>{[["dashboard","今日训练"],["matrix","能力雷达"],["journal","训练档案"],["admin","题库管理"]].map(([id,label])=><button key={id} className={view===id?"nav-active":""} onClick={()=>setView(id as View)}>{label}</button>)}</nav><div className="user-state"><span><b>{String(streak).padStart(2,"0")}</b> DAY STREAK</span><i>{rank.split(" · ")[0]}</i><button className="avatar" aria-label="用户">AI</button></div></header>}

function Dashboard({tasks:daily,openTask,score,sessions,skills,catalogSize,variantCapacity}:{tasks:Task[];openTask:(task:Task)=>void;score:number;sessions:Session[];skills:Record<string,number>;catalogSize:number;variantCapacity:number}){const dependency=sessions.length?average(sessions.slice(0,10).map(session=>session.ai_dependency_score??session.hints_used*25)):0;const judgment=sessions.length?average(sessions.slice(0,10).map(session=>session.ai_judgment_score??0)):skills["AI Judgment"]??0;const weak=Object.entries(skills).sort((a,b)=>a[1]-b[1]).slice(0,3);return <><section className="dash-hero"><div><p className="kicker">FOUR-LAYER ENGINEERING FUNNEL</p><h1>先收敛，<br/>再让 <span>AI 生成。</span></h1><p>需求 → 方案 → 实现 → 验收。每一层必须由人类批准，AI 的自由度逐层收缩；没有证据，不能宣布完成。当前 {catalogSize} 个模板、{variantCapacity}+ 个动态故障变体。</p><button className="primary big" onClick={()=>openTask(daily[0])}>进入今日工程漏斗 <b>→</b></button></div><div className="hero-meter"><div className="meter-score"><strong>{judgment||score}</strong><span>ENGINEERING CONVERGENCE</span></div><div className="meter-stats"><p><b>{sessions.length}</b><span>闭环证据</span></p><p><b>{dependency}%</b><span>AI 依赖度</span></p><p><b>{variantCapacity}+</b><span>场景变体</span></p></div></div></section><div className="loop-strip funnel-home-strip">{[["01","需求","DEFINE"],["02","方案","DESIGN"],["03","实现","BUILD"],["04","验收","PROVE"]].map(([id,zh,en],index)=><div key={id}><span>{id}</span><p><b>{en}</b>{zh}</p>{index<3&&<strong>→</strong>}</div>)}</div><section className="dashboard-grid"><main><div className="section-head"><div><p>ENGINEERING FUNNEL · NO STAGE SKIPPING</p><h2>今日真实工程模拟</h2></div><span>CONVERGE BEFORE GENERATE</span></div><div className="task-grid">{daily.map((task,index)=><button className={`task-card ${index===0?"featured":""}`} key={task.variantId??task.id} onClick={()=>openTask(task)}><div className="card-top"><span>{task.day}</span><i className={`difficulty d-${task.difficulty}`}>L{task.difficultyLevel} · {task.difficulty}</i></div><em>{task.type}</em><h3>{task.title}</h3><p>{task.summary}</p><div className="skill-chips">{task.skills.map(skill=><span key={skill}>{skill}</span>)}</div><div className="card-foot"><span>{task.scenarioClass?.replaceAll("-"," ").toUpperCase()}</span><b>进入漏斗 →</b></div></button>)}</div></main><aside className="coach-brief"><span className="ai-badge">HUMAN OWNS EVERY GATE</span><h3>为什么推荐这些？</h3><p>系统按能力弱项、漏斗层级、难度和近 30 天记录生成不重复场景，并注入需求冲突、错误方案、范围漂移和虚假完成声明。</p>{weak.map(([name,value])=><div className="mini-skills" key={name}><div><span>{name}</span><i><em style={{width:`${value}%`}}/></i><b>{value}</b></div></div>)}<blockquote>Define. Design. Build. Prove. Human decides; AI executes.</blockquote></aside></section></>}

type LoopMetrics={score:number;aiDependencyScore:number;aiJudgmentScore:number;engineeringOwnershipScore:number;specificationScore:number;releaseScore:number;systemModelingScore:number;planningScore:number;hypothesisScore:number;falsificationScore:number;observationScore:number;stateUpdateScore:number;toolSelectionScore:number;verificationScore:number;cognitiveDebtScore:number;reviewCoverage:number;understandingCoverage:number;diffReviewScore:number;scopeControlScore:number;architectureControlScore:number;changeRiskScore:number;generationReviewRatio:number;requirementQualityScore:number;solutionQualityScore:number;implementationPlanningScore:number;acceptanceQualityScore:number;engineeringConvergenceScore:number};
type TrainingProps={task:Task;phase:Phase;setPhase:(phase:Phase)=>void;observation:Observation;setObservation:(value:Observation)=>void;systemModel:SystemModel;setSystemModel:(value:SystemModel)=>void;diagnosis:Diagnosis;setDiagnosis:(value:Diagnosis)=>void;actionPlan:ActionPlan;setActionPlan:(value:ActionPlan)=>void;evidence:Evidence;setEvidence:(value:Evidence)=>void;stateUpdate:StateUpdate;setStateUpdate:(value:StateUpdate)=>void;reflection:Reflection;setReflection:(value:Reflection)=>void;reviewDecision:ReviewDecision;setReviewDecision:(value:ReviewDecision)=>void;specificationCoverage:string[];setSpecificationCoverage:(value:string[])=>void;releaseChecks:string[];setReleaseChecks:(value:string[])=>void;funnelHistory:FunnelDecision[];reopenRequirement:()=>void;workspace:Record<string,string>;setWorkspace:(value:Record<string,string>)=>void;selectedFile:string;setSelectedFile:(value:string)=>void;panel:string;selectTool:(name:string)=>void;results:TestResult[];runTests:()=>void;advanceObserve:()=>void;advanceModel:()=>void;lockDiagnosis:()=>void;advancePlan:()=>void;goEvidence:()=>void;goUpdate:()=>void;goLearn:()=>void;complete:()=>void;hints:number;requestHint:()=>void;notice:string;saving:boolean;metrics:LoopMetrics;dailyTasks:Task[];openTask:(task:Task)=>void};
function Training(p:TrainingProps){
  const stages:[Exclude<Phase,"result">,string,string][]=[["observe","Observe","感知"],["model","Model","建模"],["hypothesize","Hypothesize","假设"],["plan","Plan","规划"],["act","Act","行动"],["verify","Verify","验证"],["update","Update","更新"],["learn","Learn","复盘"]];
  const current=p.phase==="result"?stages.length-1:stages.findIndex(([phase])=>phase===p.phase);
  const funnelIndex=p.phase==="observe"?0:["model","hypothesize"].includes(p.phase)?1:["plan","act"].includes(p.phase)?2:3;
  const filled=(values:string[])=>Math.round(values.filter(value=>value.trim().length>=4).length/Math.max(1,values.length)*100);
  const funnelStages=[
    {name:"Requirement",zh:"需求",verb:"DEFINE",score:filled([p.observation.user,p.observation.why,p.observation.what,p.observation.input,p.observation.output,p.observation.constraints,p.observation.successMetric,p.observation.failureCondition])},
    {name:"Solution",zh:"方案",verb:"DESIGN",score:filled([p.systemModel.boundary,p.systemModel.currentState,p.systemModel.expectedState,p.systemModel.candidateSolutions,p.systemModel.tradeoffs,p.systemModel.risks,p.systemModel.decisionRecord])},
    {name:"Implementation",zh:"实现",verb:"BUILD",score:filled([p.actionPlan.scopeGoal,p.actionPlan.proposedFiles,p.actionPlan.impactAnalysis,p.actionPlan.candidateActions,p.reviewDecision.understanding])},
    {name:"Acceptance",zh:"验收",verb:"PROVE",score:Math.round((p.results.filter(result=>result.passed).length/4*.5+Math.min(1,p.releaseChecks.length/8)*.5)*100)},
  ];
  let content;
  if(p.phase==="observe")content=<ObservationForm task={p.task} value={p.observation} setValue={p.setObservation} submit={p.advanceObserve}/>;
  else if(p.phase==="model")content=<SystemModelForm value={p.systemModel} setValue={p.setSystemModel} submit={p.advanceModel}/>;
  else if(p.phase==="hypothesize")content=<DiagnosisForm value={p.diagnosis} setValue={p.setDiagnosis} submit={p.lockDiagnosis}/>;
  else if(p.phase==="plan")content=<ActionPlanForm task={p.task} value={p.actionPlan} setValue={p.setActionPlan} submit={p.advancePlan}/>;
  else if(p.phase==="act")content=<Lab task={p.task} workspace={p.workspace} setWorkspace={p.setWorkspace} selectedFile={p.selectedFile} setSelectedFile={p.setSelectedFile} panel={p.panel} selectTool={p.selectTool} review={p.reviewDecision} setReview={p.setReviewDecision} specificationCoverage={p.specificationCoverage} setSpecificationCoverage={p.setSpecificationCoverage} results={p.results} runTests={p.runTests} goEvidence={p.goEvidence}/>;
  else if(p.phase==="verify")content=<EvidenceForm value={p.evidence} setValue={p.setEvidence} submit={p.goUpdate}/>;
  else if(p.phase==="update")content=<StateUpdateForm task={p.task} value={p.stateUpdate} setValue={p.setStateUpdate} submit={p.goLearn}/>;
  else content=<ReflectionForm task={p.task} value={p.reflection} setValue={p.setReflection} releaseChecks={p.releaseChecks} setReleaseChecks={p.setReleaseChecks} review={p.reviewDecision} setReview={p.setReviewDecision} submit={p.complete} saving={p.saving}/>;
  return <><section className="mission-head"><div><p><span>{p.task.type}</span> {p.task.day} · L{p.task.difficultyLevel}</p><h1>{p.task.title}</h1><div>{p.task.skills.map(skill=><i key={skill}>{skill}</i>)}</div></div><aside><span>{p.task.scenarioClass?.replaceAll("-"," ").toUpperCase()}</span><b>{p.task.variantId?.split(":")[1]?.toUpperCase()??"PROJECT"}</b>{funnelIndex>0&&p.phase!=="result"&&<button onClick={p.reopenRequirement}>需求变化 · 重新打开</button>}<button onClick={()=>p.openTask(p.dailyTasks[0])}>退出任务</button></aside></section><div className="funnel-stagebar">{funnelStages.map((stage,index)=><div className={index===funnelIndex?"active":index<funnelIndex||p.phase==="result"?"done":"locked"} key={stage.name}><span>{index<funnelIndex||p.phase==="result"?"✓":`0${index+1}`}</span><p><small>{stage.verb}</small><b>{stage.name}</b><em>{stage.zh}</em></p><strong>{index>funnelIndex?"LOCKED":`${stage.score}%`}</strong></div>)}</div><div className="stagebar stagebar-eight">{stages.map(([id,en,zh],index)=><div className={index===current?"active":index<current||p.phase==="result"?"done":""} key={id}><span>{index<current||p.phase==="result"?"✓":index+1}</span><b>{en}</b><small>{zh}</small></div>)}</div>{p.phase==="result"?<Result task={p.task} metrics={p.metrics} hints={p.hints} results={p.results} next={p.dailyTasks.find(task=>task.variantId!==p.task.variantId)??p.dailyTasks[0]} openTask={p.openTask}/>:<div className="workspace"><TaskBrief task={p.task}/><main className="lab">{content}{p.notice&&<p className={`inline-notice ${p.results.length&&p.results.every(result=>result.passed)?"success":""}`}>{p.notice}</p>}</main><aside className="skill-side"><div className="aside-heading"><span>AI AS ONE TOOL</span><small>HUMAN DECIDES</small></div><div className="confidence-contrast"><span>FOUR-LAYER FUNNEL</span><strong>{funnelIndex+1}/4</strong><small>Every stage must be earned</small></div>{p.funnelHistory.length>0&&<div className="decision-history"><b>DECISION HISTORY</b>{p.funnelHistory.slice(-4).map((item,index)=><p key={`${item.at}-${index}`}><span>{item.stage}</span>{item.decision}</p>)}</div>}<div className="hint-stack">{p.hints===0?<p>先收敛，再生成。提示只能缩小搜索空间，不能替你通过阶段门。</p>:p.task.hints.slice(0,p.hints).map((hint,index)=><details open={index===p.hints-1} key={hint}><summary>第 {index+1} 级提示</summary><p>{hint}</p></details>)}</div><button className="ghost full" onClick={p.requestHint} disabled={p.hints>=3}>获取下一层提示 · {p.hints}/3</button><div className="rule"><span>ENVIRONMENT FEEDBACK</span><p>{p.task.expectedObservation}</p></div></aside></div>}</>;
}

function TaskBrief({task}:{task:Task}){return <aside className="brief"><div className="aside-heading"><span>TASK BRIEF</span><small>{task.duration} MIN</small></div><h2>{task.summary}</h2><p>{task.prompt}</p><div className="facts"><h3>KNOWN FACTS</h3>{task.facts.map(([key,value])=><p key={key}><span>{key}</span><code>{value}</code></p>)}</div><div className="criteria"><h3>ACCEPTANCE</h3>{task.criteria.map(item=><label key={item}><input type="checkbox" readOnly/> {item}</label>)}</div></aside>}
function Field({label,value,onChange,placeholder,area=true}:{label:string;value:string;onChange:(value:string)=>void;placeholder:string;area?:boolean}){return <label className="structured-field"><span>{label}</span>{area?<textarea value={value} onChange={event=>onChange(event.target.value)} placeholder={placeholder}/>:<input value={value} onChange={event=>onChange(event.target.value)} placeholder={placeholder}/>}</label>}
function ObservationForm({task,value,setValue,submit}:{task:Task;value:Observation;setValue:(value:Observation)=>void;submit:()=>void}){const set=(key:keyof Observation)=>(next:string)=>setValue({...value,[key]:next});const answers=[value.user,value.why,value.what,value.input,value.output,value.constraints,value.successMetric,value.failureCondition];const completeness=Math.round(answers.filter(item=>item.trim().length>=4).length/answers.length*100);return <div className="structured-card world-card"><div className="coach-label"><span>01 · REQUIREMENT FUNNEL</span><i>DEFINE · WHAT BEFORE HOW</i></div><blockquote>不要从一句 Prompt 跳到代码。先把业务意图收敛成可批准、可验收的需求。</blockquote><div className="funnel-meter"><div><b>REQUIREMENT COMPLETENESS</b><span>{completeness}%</span></div><i><em style={{width:`${completeness}%`}}/></i><small>{completeness<100?"Missing Requirement Detection · 仍有关键定义未收敛":"READY FOR HUMAN SIGN-OFF"}</small></div><div className="fault-banner"><b>FAULT INJECTION</b><span>{task.faultInjection}</span></div><div className="structured-grid requirement-canvas"><Field label="Who · 用户 / 利益相关者 *" value={value.user} onChange={set("user")} placeholder="谁使用、谁批准、谁承担失败后果"/><Field label="Why · 痛点与业务目的 *" value={value.why} onChange={set("why")} placeholder="为什么现在要做；不做会怎样"/><Field label="What · 唯一目标 *" value={value.what} onChange={set("what")} placeholder="要改变什么业务状态，不描述实现"/><Field label="Input · 输入定义 *" value={value.input} onChange={set("input")} placeholder="来源、格式、权限、有效范围"/><Field label="Output · 输出定义 *" value={value.output} onChange={set("output")} placeholder="用户或下游系统最终得到什么"/><Field label="Constraint · 约束 *" value={value.constraints} onChange={set("constraints")} placeholder="安全、合规、时间、成本、兼容性"/><Field label="Success Metric · 成功标准 *" value={value.successMetric} onChange={set("successMetric")} placeholder="可量化、可观察、可复现"/><Field label="Failure Condition · 失败条件 *" value={value.failureCondition} onChange={set("failureCondition")} placeholder="哪些结果即使测试通过也不能接受"/><Field label="可观察信号 *" value={value.signals} onChange={set("signals")} placeholder="日志、响应、指标、用户报告；只写观察结果"/><Field label="已知事实 *" value={value.knownFacts} onChange={set("knownFacts")} placeholder="已被证据确认的状态与约束"/><Field label="未知 / 假设 / 冲突 *" value={value.unknowns} onChange={set("unknowns")} placeholder="缺失需求、隐含假设与冲突项"/><Field label="证据来源" value={value.sources} onChange={set("sources")} placeholder="访谈 / 流程 / 数据 / 日志 / 客户复现"/></div><div className="approval-gate requirement-lock"><b>REQUIREMENT LOCK · HUMAN GATE</b><p>未批准不得进入方案层；需求发生变化时必须重新打开漏斗。</p>{[["approve","批准并锁定需求"],["reopen","保持打开，继续澄清"]].map(([id,label])=><button className={value.requirementApproval===id?"selected":""} key={id} onClick={()=>setValue({...value,requirementApproval:id as Observation["requirementApproval"]})}>{label}</button>)}</div><button className="primary" onClick={submit}>通过需求门，进入方案漏斗 <b>→</b></button></div>}
function SystemModelForm({value,setValue,submit}:{value:SystemModel;setValue:(value:SystemModel)=>void;submit:()=>void}){const set=(key:keyof SystemModel)=>(next:string)=>setValue({...value,[key]:next});const quality=Math.round([value.boundary,value.currentState,value.expectedState,value.candidateSolutions,value.tradeoffs,value.risks,value.decisionRecord].filter(item=>item.trim().length>=6).length/7*100);return <div className="structured-card world-card"><div className="coach-label"><span>02 · SOLUTION FUNNEL</span><i>DESIGN · CONVERGE BEFORE GENERATE</i></div><blockquote>AI 可以提出多个方案，但只有人类批准的架构可以进入实现。</blockquote><div className="funnel-meter"><div><b>SOLUTION QUALITY</b><span>{quality}%</span></div><i><em style={{width:`${quality}%`}}/></i><small>Candidate → Tradeoff → Risk → ADR → Architecture Freeze</small></div><div className="model-axis"><span>Current System</span><b>→ Architecture Decision →</b><span>Target Architecture</span></div><div className="structured-grid"><Field label="系统边界 *" value={value.boundary} onChange={set("boundary")} placeholder="系统、模块、人员和外部依赖"/><Field label="运行时状态" value={value.runtimeState} onChange={set("runtimeState")} placeholder="实例、队列、缓存、数据库、Feature Flag"/><Field label="当前系统 *" value={value.currentState} onChange={set("currentState")} placeholder="证据显示系统现在是什么状态"/><Field label="目标架构 *" value={value.expectedState} onChange={set("expectedState")} placeholder="业务不变量要求的目标状态"/><Field label="候选方案 *" value={value.candidateSolutions} onChange={set("candidateSolutions")} placeholder="至少两个方案：Build vs Buy / Sync vs Async / Agent vs Workflow"/><Field label="权衡矩阵 *" value={value.tradeoffs} onChange={set("tradeoffs")} placeholder="成本、复杂度、维护性、扩展性、可靠性、安全、性能"/><Field label="风险矩阵 *" value={value.risks} onChange={set("risks")} placeholder="概率、影响、缓解措施和接受条件"/><Field label="ADR / 决策记录 *" value={value.decisionRecord} onChange={set("decisionRecord")} placeholder="为什么选它、为什么不选替代方案、冻结哪些约束"/><Field label="状态转换" value={value.transition} onChange={set("transition")} placeholder="哪次事件或动作应该完成状态变化"/><Field label="调用链 *" value={value.callChain} onChange={set("callChain")} placeholder="入口 → Service → DB / Queue → 外部系统"/><Field label="数据流" value={value.dataFlow} onChange={set("dataFlow")} placeholder="关键字段在哪一层产生、变换或丢失"/><Field label="依赖图" value={value.dependencies} onChange={set("dependencies")} placeholder="同步、异步、缓存、第三方与失败传播关系"/></div><div className="approval-gate solution-lock"><b>ARCHITECTURE APPROVAL · HUMAN GATE</b><p>方案批准后冻结；AI 不得未经批准更换架构、依赖或边界。</p>{[["approve","批准并冻结架构"],["revise","要求补充权衡"],["reject","拒绝方案"]].map(([id,label])=><button className={value.solutionApproval===id?"selected":""} key={id} onClick={()=>setValue({...value,solutionApproval:id as SystemModel["solutionApproval"]})}>{label}</button>)}</div><button className="primary" onClick={submit}>通过方案门，验证实现假设 <b>→</b></button></div>}
function DiagnosisForm({value,setValue,submit}:{value:Diagnosis;setValue:(value:Diagnosis)=>void;submit:()=>void}){const set=(key:keyof Diagnosis)=>(next:string)=>setValue({...value,[key]:next});return <div className="structured-card"><div className="coach-label"><span>AI COACH</span><i>HUMAN FIRST</i></div><blockquote>先留下可被推翻的判断。</blockquote><div className="structured-grid"><Field label="观察到的现象 *" value={value.phenomenon} onChange={set("phenomenon")} placeholder="只写可观察事实，不解释原因"/><Field label="已知事实" value={value.facts} onChange={set("facts")} placeholder="日志、接口响应、数据状态"/><Field label="根因假设 *" value={value.hypothesis} onChange={set("hypothesis")} placeholder="我认为最可能是……因为……"/><Field label="第一个检查点 *" value={value.firstCheckpoint} onChange={set("firstCheckpoint")} placeholder="我会先检查……"/><Field label="支持证据" value={value.supportingEvidence} onChange={set("supportingEvidence")} placeholder="如果看到……会支持假设"/><Field label="反证条件 *" value={value.counterEvidence} onChange={set("counterEvidence")} placeholder="如果看到……这个假设就不成立"/><Field label="下一个最小实验" value={value.nextExperiment} onChange={set("nextExperiment")} placeholder="用最小成本区分两个可能原因"/></div><button className="primary" onClick={submit}>锁定判断，进入工具 <b>→</b></button></div>}
function ActionPlanForm({task,value,setValue,submit}:{task:Task;value:ActionPlan;setValue:(value:ActionPlan)=>void;submit:()=>void}){const set=(key:keyof ActionPlan)=>(next:string|number)=>setValue({...value,[key]:next});const budget=task.changeBudget;return <div className="structured-card world-card"><div className="coach-label"><span>04 · PLAN + APPROVE</span><i>PLAN BEFORE CODE</i></div><blockquote>AI 只能在被批准的范围和预算内行动。</blockquote>{budget&&<div className="change-budget"><div><span>FILE LIMIT</span><b>{budget.maxFiles}</b></div><div><span>LINE LIMIT</span><b>{budget.maxLines}</b></div><div><span>MODULE LIMIT</span><b>{budget.maxModules}</b></div><div><span>DEPENDENCY</span><b>{budget.maxDependencies}</b></div><div><span>MIGRATION</span><b>{budget.maxMigrations}</b></div></div>}<div className="structured-grid"><Field label="本轮唯一目标 *" value={value.scopeGoal} onChange={set("scopeGoal")} placeholder="一个任务、一个关注点、一个可验收结果"/><Field label="拟修改文件清单 *" value={value.proposedFiles} onChange={set("proposedFiles")} placeholder="明确文件；清单外默认禁止修改"/><Field label="影响分析 *" value={value.impactAnalysis} onChange={set("impactAnalysis")} placeholder="API / DB / 前端 / 后端 / 安全 / 回归 / 运维爆炸半径"/><Field label="明确排除的变更" value={value.excludedChanges} onChange={set("excludedChanges")} placeholder="不重构、不升级依赖、不改目录、不加额外功能"/><Field label="本轮上下文预算" value={value.contextBudget} onChange={set("contextBudget")} placeholder="只提供相关架构、业务约束、冻结决策和验收标准"/><Field label="候选动作 *" value={value.candidateActions} onChange={set("candidateActions")} placeholder="至少列出两个可选动作，并说明差异"/><Field label="下一最佳动作 *" value={value.nextBestAction} onChange={set("nextBestAction")} placeholder="现在先做什么，为什么最能缩小搜索空间"/><label className="structured-field"><span>选择工具 *</span><select value={value.selectedTool} onChange={event=>set("selectedTool")(event.target.value)}><option value="">选择一个工具</option>{task.tools?.map(tool=><option key={tool} value={tool}>{toolNames[tool]??tool}</option>)}</select></label><Field label="预期观察 *" value={value.expectedObservation} onChange={set("expectedObservation")} placeholder="假设成立 / 不成立时环境分别返回什么"/><label className="structured-field"><span>信息增益 · {value.informationGain}%</span><input aria-label="信息增益" type="range" min="0" max="100" value={value.informationGain} onChange={event=>set("informationGain")(Number(event.target.value))}/></label><label className="structured-field"><span>行动成本</span><select value={value.cost} onChange={event=>set("cost")(event.target.value)}><option value="low">低 · 只读检查</option><option value="medium">中 · 可逆变更</option><option value="high">高 · 生产影响</option></select></label><label className="structured-field"><span>行动风险</span><select value={value.risk} onChange={event=>set("risk")(event.target.value)}><option value="low">低</option><option value="medium">中</option><option value="high">高 · 需单独批准</option></select></label><Field label="失败与降级计划" value={value.fallback} onChange={set("fallback")} placeholder="观察不符时如何重规划；高风险动作如何回滚"/></div><div className="approval-gate"><b>HUMAN APPROVAL GATE</b><p>范围和文件清单一旦批准即锁定；额外建议不会自动执行。</p>{[["approve","批准当前小批次"],["split","要求继续拆分"],["reject","拒绝计划"]].map(([id,label])=><button className={value.approvalDecision===id?"selected":""} key={id} onClick={()=>setValue({...value,approvalDecision:id as ActionPlan["approvalDecision"]})}>{label}</button>)}</div><button className="primary" onClick={submit}>通过审批门，开始小步实现 <b>→</b></button></div>}
function StateUpdateForm({task,value,setValue,submit}:{task:Task;value:StateUpdate;setValue:(value:StateUpdate)=>void;submit:()=>void}){const set=(key:keyof StateUpdate)=>(next:string)=>setValue({...value,[key]:next});return <div className="structured-card world-card"><div className="coach-label"><span>07 · UPDATE</span><i>ENVIRONMENT FEEDBACK</i></div><blockquote>行动改变系统；观察必须改变你的模型。</blockquote><div className="feedback-feed">{task.environmentFeedback?.map((item,index)=><p key={item}><span>0{index+1}</span>{item}</p>)}</div><div className="structured-grid"><Field label="行动结果 *" value={value.actionResult} onChange={set("actionResult")} placeholder="行动执行成功、失败或部分成功；不要只写预期"/><Field label="新观察 *" value={value.newObservation} onChange={set("newObservation")} placeholder="环境返回了什么新的运行时证据"/><Field label="世界模型如何变化 *" value={value.modelChanged} onChange={set("modelChanged")} placeholder="当前状态、边界、数据流或依赖图哪里需要修正"/><Field label="假设状态 *" value={value.hypothesisStatus} onChange={set("hypothesisStatus")} placeholder="接受、拒绝或降低哪个假设的可信度，为什么"/><Field label="重新规划的下一步" value={value.replannedAction} onChange={set("replannedAction")} placeholder="如果仍未闭环，下一最佳动作是什么"/></div><button className="primary" onClick={submit}>更新认知，进入复盘 <b>→</b></button></div>}
function Lab({task,workspace,setWorkspace,selectedFile,setSelectedFile,panel,selectTool,review,setReview,specificationCoverage,setSpecificationCoverage,results,runTests,goEvidence}:{task:Task;workspace:Record<string,string>;setWorkspace:(value:Record<string,string>)=>void;selectedFile:string;setSelectedFile:(value:string)=>void;panel:string;selectTool:(name:string)=>void;review:ReviewDecision;setReview:(value:ReviewDecision)=>void;specificationCoverage:string[];setSpecificationCoverage:(value:string[])=>void;results:TestResult[];runTests:()=>void;goEvidence:()=>void}){const tools=task.tools??["code","logs","tests"];return <><AIReviewLab task={task} review={review} setReview={setReview} specificationCoverage={specificationCoverage} setSpecificationCoverage={setSpecificationCoverage}/><div className="lab-top"><div className="tabs">{tools.map(tool=><button className={panel===tool?"selected":""} key={tool} onClick={()=>selectTool(tool)}>{toolNames[tool]??tool}</button>)}</div><span>● ENGINEERING SIMULATOR · ISOLATED</span></div>{panel==="code"?<div className="multi-editor"><div className="file-tree">{Object.keys(workspace).map(path=><button className={selectedFile===path?"selected":""} key={path} onClick={()=>setSelectedFile(path)}>{path}</button>)}</div><div className="code-wrap"><div className="filebar">{selectedFile}<b>AI GENERATED · HUMAN OWNED</b></div><textarea className="editor" value={workspace[selectedFile]??""} onChange={event=>setWorkspace({...workspace,[selectedFile]:event.target.value})} spellCheck={false} aria-label="代码编辑区"/></div></div>:panel==="tests"?<TestEvidence task={task} results={results}/>:<ToolOutput title={toolNames[panel]?.toUpperCase()??panel.toUpperCase()} rows={toolRows(panel,task,workspace)}/>}<div className="actions"><button className="ghost" onClick={runTests}>运行自动验收</button><button className="primary" onClick={goEvidence}>进入证据验证 <b>→</b></button></div></>}

function toggleItem(items:string[],item:string){return items.includes(item)?items.filter(value=>value!==item):[...items,item]}
function AIReviewLab({task,review,setReview,specificationCoverage,setSpecificationCoverage}:{task:Task;review:ReviewDecision;setReview:(value:ReviewDecision)=>void;specificationCoverage:string[];setSpecificationCoverage:(value:string[])=>void}){const submission=task.aiSubmission;const budget=task.changeBudget;const files=submission?.filesChanged??submission?.changedFiles.length??0;const lines=submission?.linesAdded??0;const dependencies=submission?.newDependencies??0;const migrations=submission?.migrations??0;const capacity=Math.max(1,review.reviewCapacity);const ratio=Math.round(lines/capacity*100)/100;const debt=Math.min(100,Math.round((budget?(files/budget.maxFiles+lines/budget.maxLines+(dependencies/(budget.maxDependencies||1))+(migrations/(budget.maxMigrations||1))):1)*25));const overBudget=Boolean(budget&&(files>budget.maxFiles||lines>budget.maxLines||dependencies>budget.maxDependencies||migrations>budget.maxMigrations));const specialApproval=Boolean(budget?.impactAnalysisRequired||dependencies>0||migrations>0);return <section className="ai-review-lab"><div className="ai-claim"><span>AI GENERATED PULL REQUEST</span><strong>{submission?.confidence??0}% <small>AI CONFIDENCE</small></strong><h3>{submission?.claim}</h3><p>{submission?.rationale}</p><div>{submission?.changedFiles.map(file=><code key={file}>M {file}</code>)}</div></div><div className={`debt-dashboard ${overBudget?"danger":""}`}><div><span>COGNITIVE DEBT</span><b>{debt}</b><small>{debt>=70?"This Change Is Too Large to Review Safely":"Within Reviewable Range"}</small></div><div><span>FILES</span><b>{files} / {budget?.maxFiles}</b><small>{files>(budget?.maxFiles??99)?"OVER BUDGET":"OK"}</small></div><div><span>LINES</span><b>+{lines}</b><small>LIMIT {budget?.maxLines}</small></div><div><span>GEN / REVIEW</span><b>{ratio}×</b><small>{ratio>1?"AI EXCEEDS CAPACITY":"BALANCED"}</small></div><div><span>DEPENDENCY / DB</span><b>{dependencies} / {migrations}</b><small>SEPARATE APPROVAL</small></div></div>{overBudget&&<div className="stop-warning"><b>STOP · REVIEW BEFORE GENERATE MORE</b><span>AI 输出已经超过人工审查容量。拆分本轮任务，理解当前 Diff 后再继续。</span></div>}<div className="guardrail-strip"><b>ARCHITECTURE GUARDRAILS</b>{task.guardrails?.map(item=><span key={item}>□ {item}</span>)}</div><div className="review-decision"><h3>Diff Review Gate · 理解后才能继续</h3><div className="decision-buttons scope-actions">{[["accept","整包接受"],["reject","拒绝"],["split","拆分"],["rollback","回滚"],["smaller","要求更小改动"]].map(([value,label])=><button className={review.scopeDecision===value?"selected":""} key={value} onClick={()=>setReview({...review,scopeDecision:value as ReviewDecision["scopeDecision"],decision:value==="accept"?"accept":value==="reject"||value==="rollback"?"reject":"changes"})}>{label}</button>)}</div><label className="capacity-slider">本轮人工审查容量 <b>{review.reviewCapacity} 行</b><input aria-label="本轮人工审查容量" type="range" min="40" max="1000" step="20" value={review.reviewCapacity} onChange={event=>setReview({...review,reviewCapacity:Number(event.target.value)})}/></label><div className="risk-picker"><span>最高风险等级</span>{["P0","P1","P2","P3"].map(level=><button className={review.riskLevel===level?"selected":""} key={level} onClick={()=>setReview({...review,riskLevel:level as ReviewDecision["riskLevel"]})}>{level}</button>)}</div><label className="drift-check"><input type="checkbox" checked={review.architectureDriftDetected} onChange={event=>setReview({...review,architectureDriftDetected:event.target.checked})}/> 检测到未经授权的架构、目录或依赖漂移</label>{specialApproval&&<label className="drift-check approval-check"><input type="checkbox" checked={review.impactApproved} onChange={event=>setReview({...review,impactApproved:event.target.checked})}/> 我已单独审查跨模块 / 依赖 / 数据库影响、兼容性和回滚</label>}<div className="structured-grid"><Field label="发现的问题与遗漏 *" value={review.issues} onChange={issues=>setReview({...review,issues})} placeholder="范围、架构、依赖、迁移、安全、回归或运维问题"/><Field label="范围决定理由 *" value={review.rationale} onChange={rationale=>setReview({...review,rationale})} placeholder="为什么接受、拆分、拒绝或回滚"/><Field label="逐文件解释 / 我理解了什么 *" value={review.understanding} onChange={understanding=>setReview({...review,understanding})} placeholder="改了什么、为什么改、调用链和数据流如何变化"/><Field label="失败时如何回滚 *" value={review.rollback} onChange={rollback=>setReview({...review,rollback})} placeholder="明确撤销、降级或恢复步骤"/><Field label="要求 AI 如何缩小" value={review.revisionRequest} onChange={revisionRequest=>setReview({...review,revisionRequest})} placeholder="限定文件、行数、模块、依赖和验收证据"/></div><div className="suggestion-queue"><div><b>AI EXTRA SUGGESTIONS</b><span>默认 DEFERRED · 不自动执行</span></div>{task.aiSuggestions?.map(suggestion=>{const status=review.suggestionDecisions[suggestion.id]??"defer";return <article key={suggestion.id}><p><strong>{suggestion.label}</strong><small>{suggestion.impact} · COST {suggestion.cost.toUpperCase()}</small></p><section>{[["accept","接受"],["reject","拒绝"],["defer","延期"],["ignore","忽略"]].map(([id,label])=><button className={status===id?"selected":""} key={id} onClick={()=>setReview({...review,suggestionDecisions:{...review.suggestionDecisions,[suggestion.id]:id as "accept"|"reject"|"defer"|"ignore"}})}>{label}</button>)}</section></article>})}</div><div className="trust-calibration"><label>审查前信任 <b>{review.trustBefore}%</b><input aria-label="审查前信任" type="range" min="0" max="100" value={review.trustBefore} onChange={event=>setReview({...review,trustBefore:Number(event.target.value)})}/></label><label>证据后信任 <b>{review.trustAfter}%</b><input aria-label="证据后信任" type="range" min="0" max="100" value={review.trustAfter} onChange={event=>setReview({...review,trustAfter:Number(event.target.value)})}/></label></div></div><div className="spec-coverage"><div><b>SPECIFICATION COMPLETENESS</b><span>{Math.round(specificationCoverage.length/Math.max(1,task.specificationDimensions?.length??11)*100)}%</span></div><p>达到验收、回归和证据要求后停止，不允许无限优化：</p><section>{task.specificationDimensions?.map(item=><button className={specificationCoverage.includes(item)?"selected":""} key={item} onClick={()=>setSpecificationCoverage(toggleItem(specificationCoverage,item))}>{specificationCoverage.includes(item)?"✓":"＋"} {item}</button>)}</section></div></section>}
function diffRows(task:Task,workspace:Record<string,string>){const changed=Object.entries(workspace).filter(([path,content])=>!task.files?.some(file=>file.path===path&&file.content===content));return changed.length?changed.map(([path,content])=>`M ${path} · ${content.split("\n").length} lines · working tree changed`):["working tree clean","先完成你的最小改动"]}
function toolRows(panel:string,task:Task,workspace:Record<string,string>){if(panel==="logs")return task.logs;if(panel==="network")return task.network??[];if(panel==="sql")return task.sql??[];if(panel==="env")return task.env??[];if(panel==="diff")return diffRows(task,workspace);if(panel==="api")return["POST /api/action → 200 64ms","x-trace-id: forge-lab","response state differs from persisted state","inspect authorization and idempotency before retry"];if(panel==="db")return["record state=PENDING version=17","last_updated_at unchanged after request","unique constraints intact","transaction visibility: READ COMMITTED"];if(panel==="docker")return["service api healthy","worker restart_count=3","queue consumer lag detected","container image unchanged"];if(panel==="search")return["3 references for target symbol","2 callers across module boundary","1 state transition without test coverage","search narrowed investigation scope"];if(panel==="runtime")return["region=ap-southeast-1 instance=6","cache hit ratio=91%","feature flag safe=true","runtime feedback captured for model update"];return["tool ready","select an observation target"]}
function ToolOutput({title,rows}:{title:string;rows:string[]}){return <div className="terminal"><div>$ {title.toLowerCase()}</div>{rows.map((row,index)=><p className={/error|warn|failed|timeout|duplicate|0 /i.test(row)?"warn":""} key={`${row}-${index}`}><b>{String(index+1).padStart(2,"0")}</b>{row}</p>)}<i>▋</i></div>}
function TestEvidence({task,results}:{task:Task;results:TestResult[]}){const passed=results.filter(result=>result.passed).length;return <div className="test-panel evidence-tests"><div className="test-summary"><span>{results.length?`${passed} / 4 PASSED`:"READY · EXPANDABLE EVIDENCE"}</span><p>acceptance / {task.id}.spec</p></div>{task.criteria.map((criterion,index)=>{const result=results[index];return <details className={result&&!result.passed?"test-failed":""} key={criterion}><summary><span className={result?.passed?"test-pass":result?"test-fail":"test-idle"}>{result?.passed?"✓":result?"×":"○"}</span><b>{criterion}</b><code>CASE 0{index+1}</code></summary>{result?<div className="test-detail"><p><span>输入 / 操作</span>{result.input}</p><p><span>实际输出</span>{result.actual}</p><p><span>数据库状态</span>{result.databaseState}</p><p><span>证明理由</span>{result.why}</p></div>:<p className="test-empty">运行自动验收后显示输入、输出、数据状态和证明理由。</p>}</details>})}</div>}
function EvidenceForm({value,setValue,submit}:{value:Evidence;setValue:(value:Evidence)=>void;submit:()=>void}){const set=(key:keyof Evidence)=>(next:string)=>setValue({...value,[key]:next});return <div className="structured-card"><div className="coach-label"><span>EVIDENCE FIRST</span><i>ACCEPTANCE</i></div><blockquote>通过，不等于已经证明。</blockquote><div className="structured-grid"><Field label="执行命令 / 输入 *" value={value.action} onChange={set("action")} placeholder="运行了什么、输入是什么"/><Field label="实际输出 *" value={value.actual} onChange={set("actual")} placeholder="不是预期输出，而是实际观察"/><Field label="数据库 / 状态变化" value={value.dataState} onChange={set("dataState")} placeholder="写入、读取、计数或副作用"/><Field label="为什么足以证明 *" value={value.reason} onChange={set("reason")} placeholder="把证据与业务不变量连接起来"/></div><button className="primary" onClick={submit}>提交证据，进入复盘 <b>→</b></button></div>}
function ReflectionForm({task,value,setValue,releaseChecks,setReleaseChecks,review,setReview,submit,saving}:{task:Task;value:Reflection;setValue:(value:Reflection)=>void;releaseChecks:string[];setReleaseChecks:(value:string[])=>void;review:ReviewDecision;setReview:(value:ReviewDecision)=>void;submit:()=>void;saving:boolean}){const set=(key:keyof Reflection)=>(next:string)=>setValue({...value,[key]:next});return <div className="structured-card ownership-card"><div className="coach-label"><span>04 · ACCEPTANCE FUNNEL</span><i>PROVE · EVIDENCE BEFORE DONE</i></div><blockquote>AI 不能宣布完成。只有期望状态与观察状态一致，并由人类批准，任务才算 Done。</blockquote><div className="release-checklist"><div><b>AI COMPLETION VERIFICATION / DEFINITION OF DONE</b><span>{releaseChecks.length}/{task.completionClaims?.length??12}</span></div><section>{task.completionClaims?.map(item=><button className={releaseChecks.includes(item)?"selected":""} key={item} onClick={()=>setReleaseChecks(toggleItem(releaseChecks,item))}>{releaseChecks.includes(item)?"✓":"□"} {item}</button>)}</section></div><div className="structured-grid"><Field label="最初判断" value={value.initialJudgment} onChange={set("initialJudgment")} placeholder="一开始我认为……"/><Field label="真实根因 *" value={value.actualRootCause} onChange={set("actualRootCause")} placeholder="最终证据指向……"/><Field label="错误假设" value={value.wrongAssumption} onChange={set("wrongAssumption")} placeholder="我忽略或误判了……"/><Field label="关键证据 *" value={value.keyEvidence} onChange={set("keyEvidence")} placeholder="真正改变判断的是……"/><Field label="为什么选择这个方案" value={value.designRationale} onChange={set("designRationale")} placeholder="设计理由与约束"/><Field label="替代方案" value={value.alternative} onChange={set("alternative")} placeholder="为什么没有选择它"/><Field label="最大风险" value={value.largestRisk} onChange={set("largestRisk")} placeholder="最坏情况下会发生什么"/><Field label="什么条件下需要重构" value={value.refactorTrigger} onChange={set("refactorTrigger")} placeholder="明确触发条件，不提前过度设计"/><Field label="哪层提示有效" value={value.helpfulHint} onChange={set("helpfulHint")} placeholder="提示如何缩小了搜索空间"/><Field label="下次第一步 *" value={value.nextFirstStep} onChange={set("nextFirstStep")} placeholder="遇到同类问题我会先……"/></div><label className="final-approval"><input type="checkbox" checked={review.finalApproval} onChange={event=>setReview({...review,finalApproval:event.target.checked})}/><span><b>FINAL HUMAN APPROVAL</b> 我已检查 Changed Files、Tests、API、Database、Permissions、Logs、Regression、Security、Performance 与 Rollback，并接受最终工程责任。</span></label><button className="primary" onClick={submit} disabled={saving}>{saving?"正在保存责任证据…":"批准验收并完成漏斗"} <b>→</b></button></div>}
function Result({task,metrics,hints,results,next,openTask}:{task:Task;metrics:LoopMetrics;hints:number;results:TestResult[];next:Task;openTask:(task:Task)=>void}){const loopScores=[["Requirement",metrics.requirementQualityScore],["Solution",metrics.solutionQualityScore],["Implementation",metrics.implementationPlanningScore],["Acceptance",metrics.acceptanceQualityScore],["Convergence",metrics.engineeringConvergenceScore],["Cognitive Debt",metrics.cognitiveDebtScore],["Scope Control",metrics.scopeControlScore],["Gen / Review",`${metrics.generationReviewRatio}×`]] as const;return <section className="result-view"><div className="result-hero"><p>DEFINE · DESIGN · BUILD · PROVE</p><h2>{results.filter(result=>result.passed).length} / 4 <span>通过</span></h2><div>{task.criteria.map(criterion=><i key={criterion}>✓ {criterion}</i>)}</div></div><div className="review-card"><span>FOUR-LAYER FUNNEL · ALL GATES EARNED</span><h3>先收敛，<span>再生成。</span></h3><p>评分来自需求完整度、方案权衡、实现边界、Diff 理解与可复现验收证据。每一层都由人类批准，AI 不能自行跳级或宣布完成。</p><div className="loop-score-grid">{loopScores.map(([name,value])=><p key={name}><b>{name}</b><span>{value}</span></p>)}</div><div className="review-signals six"><p><b>AI Judgment</b>{metrics.aiJudgmentScore}</p><p><b>Ownership</b>{metrics.engineeringOwnershipScore}</p><p><b>Specification</b>{metrics.specificationScore}%</p><p><b>Release Ready</b>{metrics.releaseScore}%</p><p><b>AI 依赖度</b>{metrics.aiDependencyScore}%</p><p><b>工程总分</b>{metrics.score}</p></div><blockquote>{hints===0?"本次四层决策均由你独立完成。":"提示只缩小搜索空间；每一层的最终批准仍由你控制。"} Every stage must be earned.</blockquote><small>✓ 需求、架构、实现、Diff、证据和最终批准历史已保存</small></div><div className="result-skills"><p>30-DIMENSION MATRIX · UPDATED</p><h3>能力增量</h3>{Object.entries(task.gains).map(([name,value])=><div key={name}><span>{name}</span><i>+{Math.max(1,Math.round(value*(metrics.score/100)*.45))}</i></div>)}<button className="primary" onClick={()=>openTask(next)}>开始下一个工程漏斗 <b>→</b></button></div></section>}

function SkillMatrix({skills,sessions,score,rank}:{skills:Record<string,number>;sessions:Session[];score:number;rank:string}){const sorted=Object.entries(skills).sort((a,b)=>b[1]-a[1]);const dependency=sessions.length?average(sessions.map(item=>item.ai_dependency_score??item.hints_used*25)):0;const judgment=sessions.length?average(sessions.filter(item=>item.ai_judgment_score>0).map(item=>item.ai_judgment_score)):skills["AI Judgment"]??0;const ownership=sessions.length?average(sessions.filter(item=>item.engineering_ownership_score>0).map(item=>item.engineering_ownership_score)):skills["Engineering Ownership"]??0;return <section className="profile-page"><div className="profile-head"><p>FOUR-LAYER FUNNEL / HUMAN-CONTROLLED DEVELOPMENT</p><h1>从业务意图，<br/><span>收敛到工程证据。</span></h1><div><strong>{score}</strong><span>工程收敛分<br/><b>{rank}</b></span></div></div><div className="metric-cards"><article><span>AI JUDGMENT</span><strong>{judgment}</strong><p>挑战错误建议，以证据校准信任</p></article><article><span>ENGINEERING OWNERSHIP</span><strong>{ownership}</strong><p>拥有需求、架构、范围、验收与最终责任</p></article><article><span>AI DEPENDENCY</span><strong>{dependency}%</strong><p>越低代表越能独立通过每一层阶段门</p></article></div><div className="matrix-grid"><div className="matrix-list"><div className="section-head"><div><p>FUNNEL + WORLD MODEL + AI CONTROL</p><h2>三十维 AI 原生工程能力矩阵</h2></div><span>{sessions.length} 个闭环证据样本</span></div>{sorted.map(([name,value],index)=><div className="matrix-row" key={name}><span>{String(index+1).padStart(2,"0")}</span><b>{name}</b><i><em style={{width:`${value}%`}}/></i><strong>{value}</strong><small>{value>=80?"L5":value>=68?"L4":value>=55?"L3":value>=42?"L2":"L1"}</small></div>)}</div><aside className="growth-plan"><span>ENGINEERING CONVERGENCE</span><h3>从使用 AI 到拥有每个决策门</h3>{[["L1","Requirement Observer"],["L2","Solution Reviewer"],["L3","Scope Controller"],["L4","AI Orchestrator"],["L5","Engineering Owner"]].map(([level,name])=><div key={level}><b>{level}</b><p><strong>{name}</strong><span>{level==="L5"?"收敛需求、冻结架构并对真实结果负责":"逐步增加需求、方案、实现与验收能力"}</span></p></div>)}<blockquote>下一训练重点：{sorted.slice(-3).map(([name])=>name).join("、")}</blockquote></aside></div></section>}
function Journal({sessions,openTask,fallback}:{sessions:Session[];openTask:(task:Task)=>void;fallback:Task}){return <section className="journal-page"><div className="section-head large"><div><p>ENGINEERING JOURNAL</p><h1>每一次判断，<br/>都成为下一次的经验。</h1></div><span>{sessions.length} RECORDS</span></div>{sessions.length===0?<div className="empty-journal"><span>00</span><h2>还没有训练证据</h2><p>完成任务后，这里会保留结构化诊断、验收证据、反思和 AI 依赖度。</p><button className="primary" onClick={()=>openTask(fallback)}>开始第一次训练 <b>→</b></button></div>:<div className="journal-list">{sessions.map((session,index)=><article key={`${session.id}-${index}`}><div><span>{String(sessions.length-index).padStart(2,"0")}</span><time>{new Date(session.completed_at).toLocaleDateString("zh-CN")}</time></div><main><p>{session.variant_id}</p><h2>{session.task_title}</h2><section><div><b>结构化判断</b><p>{textFrom(session.diagnosis)}</p></div><div><b>验收证据</b><p>{textFrom(session.evidence)}</p></div></section></main><aside><strong>{session.score}</strong><span>SCORE</span><p>AI 依赖 {session.ai_dependency_score??session.hints_used*25}% · 提示 {session.hints_used}/3</p></aside></article>)}</div>}</section>}

function Admin({catalogSize}:{catalogSize:number}){const [key,setKey]=useState("");const [items,setItems]=useState<Array<{id:string;title:string;type:string;difficultyLevel:number;published:boolean}>>([]);const [status,setStatus]=useState("");const [form,setForm]=useState({title:"",summary:"",context:"",solution:""});async function load(){setStatus("正在验证并载入题库…");const response=await fetch("/api/tasks?mode=catalog",{headers:{"x-forge-admin-key":key}});const data=await response.json();if(!response.ok){setStatus("管理密钥不正确。");return}setItems([...(data.builtIn??[]),...(data.custom??[]).map((item:{id:string;title:string;published:boolean;task:{type:string;difficultyLevel:number}})=>({id:item.id,title:item.title,published:item.published,type:item.task.type,difficultyLevel:item.task.difficultyLevel}))]);setStatus(`已载入 ${data.builtIn.length} 个内置模板与 ${data.custom.length} 个自定义任务。`)}async function create(){const response=await fetch("/api/tasks",{method:"POST",headers:{"content-type":"application/json","x-forge-admin-key":key},body:JSON.stringify({...form,type:"REAL PROJECT",difficultyLevel:3,published:true})});if(!response.ok){setStatus("发布失败，请检查必填字段和管理密钥。");return}setForm({title:"",summary:"",context:"",solution:""});await load()}return <section className="admin-page"><div className="section-head large"><div><p>ADMIN / TASK OPERATIONS</p><h1>动态题库管理</h1></div><span>{catalogSize} TEMPLATES · {catalogSize*5}+ VARIANTS</span></div><div className="admin-grid"><aside><span>SECURE ACCESS</span><h2>管理员验证</h2><p>管理写入由服务端密钥保护。密钥只保存在本次页面内存中，不写入浏览器存储。</p><input type="password" value={key} onChange={event=>setKey(event.target.value)} placeholder="FORGE_ADMIN_KEY"/><button className="primary" onClick={load}>验证并载入题库</button>{status&&<p className="admin-status">{status}</p>}</aside><main><h2>发布真实工程任务</h2><div className="admin-form"><Field area={false} label="任务标题" value={form.title} onChange={title=>setForm({...form,title})} placeholder="例如：修复退款对账偏差"/><Field label="业务背景" value={form.summary} onChange={summary=>setForm({...form,summary})} placeholder="用户、场景、影响与限制"/><Field label="初始代码 / 项目上下文" value={form.context} onChange={context=>setForm({...form,context})} placeholder="可粘贴多文件任务的入口内容"/><Field label="内部验收参考（学员不可见）" value={form.solution} onChange={solution=>setForm({...form,solution})} placeholder="用于生成验收点，不直接显示给学员"/><button className="primary" onClick={create}>发布到动态题库 <b>→</b></button></div></main></div>{items.length>0&&<div className="catalog-table"><div><b>任务</b><b>类型</b><b>难度</b><b>状态</b></div>{items.map(item=><div key={item.id}><span>{item.title}<small>{item.id}</small></span><span>{item.type}</span><span>L{item.difficultyLevel}</span><span>{item.published?"已发布":"草稿"}</span></div>)}</div>}</section>}
